!function(a){function n(n){for(var m,r,t=n[0],o=n[1],c=n[2],l=0,g=[];l<t.length;l++)r=t[l],Object.prototype.hasOwnProperty.call(i,r)&&i[r]&&g.push(i[r][0]),i[r]=0;for(m in o)Object.prototype.hasOwnProperty.call(o,m)&&(a[m]=o[m]);for(d&&d(n);g.length;)g.shift()();return p.push.apply(p,c||[]),e()}function e(){for(var a,n=0;n<p.length;n++){for(var e,r=p[n],t=!0,o=1;o<r.length;o++)e=r[o],0!==i[e]&&(t=!1);t&&(p.splice(n--,1),a=m(m.s=r[0]))}return a}function m(n){if(r[n])return r[n].exports;var e=r[n]={i:n,l:!1,exports:{}};return a[n].call(e.exports,e,e.exports,m),e.l=!0,e.exports}var r={},i={39:0},p=[];m.m=a,m.c=r,m.d=function(a,n,e){m.o(a,n)||Object.defineProperty(a,n,{enumerable:!0,get:e})},m.r=function(a){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(a,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(a,"__esModule",{value:!0})},m.t=function(a,n){if(1&n&&(a=m(a)),8&n)return a;if(4&n&&"object"==typeof a&&a&&a.__esModule)return a;var e=Object.create(null);if(m.r(e),Object.defineProperty(e,"default",{enumerable:!0,value:a}),2&n&&"string"!=typeof a)for(var r in a)m.d(e,r,function(n){return a[n]}.bind(null,r));return e},m.n=function(a){var n=a&&a.__esModule?function(){return a.default}:function(){return a};return m.d(n,"a",n),n},m.o=function(a,n){return Object.prototype.hasOwnProperty.call(a,n)},m.p="";var t=window.webpackJsonp=window.webpackJsonp||[],o=t.push.bind(t);t.push=n,t=t.slice();for(var c=0;c<t.length;c++)n(t[c]);var d=o;p.push([192,0]),e()}({192:function(a,n,e){"use strict";e.r(n);var m=e(0);Object(m.a)("de","army",e(193),e(1))},193:function(a){a.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"火炮","link":"de_army#de_army_cannon"}],"model":"88mm Flak18型高射炮","description":"<p>88mm高射炮是二战德军一种极为出色的大威力火炮，它不但是一种对付高空目标的防空炮，更是一种对付中、重型坦克的利器。该炮在二战前的西班牙内战中就开始显露头角，在防空和地面攻击（主要是对炮阵地的攻击）都取得了不错的战绩，二战中，在德军的各战场上，在与苏军与盟军中、重型坦克的对抗中，更是战绩辉煌。</p><p>88mm高射炮主要型号有Flak18、Flak36、Flak37和Flak41型，Flak18在1937年就开始服役。最初88mm高射炮只装备给德军的空军防空部队，是纳粹德国空军高炮部队的标准配备，后因其在陆战中的突出表现，陆军与党卫军部队也成立了装备88mm高炮的炮兵营，二战爆发前，德军拥有约2000门88mm高射炮（除Flak18外，还包括Flak36/37型)，这些高射炮除了作空防用外，更多的是在战场上作地面火力支援，对抗敌方的中、重型坦克，工事甚至作野战炮用。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_cannonFlak18_11.jpg","description":"<h6>88mm Flak18型高射炮</h6><p></p><p>技术数据：</p><p>火炮口径：88mm；</p><p>火炮移动台架：Sd.Ah.201；</p><p>炮长：5.8米（运输时7.7米）；炮宽：前2.1米（运输时2.19米），后2.3米；</p><p>炮高：2.4米；</p><p>脚支架宽度：5.14米；</p><p>炮管长：4.7米；膛线长：4米（32槽右旋）</p><p>火炮重：战斗4.986吨，运输8.2吨；</p><p>火炮射界（水平方向）：360度，火炮射角（垂直方向）：-3度～+85度；</p><p>射速（每分钟）：15发；</p><p>水平直射最远射程：14813米；</p><p>最高有效射距：9900米；</p><p>70度时最高射距：7620米；</p><p>炮弹初速：820米/秒；</p><p>炮班人员：11～12人（包括牵引拖曳车的驾驶员）。</p>","caption":""}],"part2title":"战场上的88mm Flak18型高射炮（对地作战篇）","part2description":"","part2content":[{"image":"imgs/de/army/de_army_cannonFlak18_21.jpg","description":"1941-1942年冬季，东线苏联战场，一门德军（不明单位）的88mm Flak18高射炮。炮管上用黄色条纹标注着该炮作战所取得击毁坦克、轮船与飞机数量的战绩。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_22.jpg","description":"1942年10月，北非战场埃及阿拉曼地区，隶属德军第19高射炮师的一门88mm Flak18高射炮。炮管上有该炮作战战绩的标志，其中有击毁英军船舰船的数量。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_23.jpg","description":"1942年3月，北非战场利比亚地区，隶属德军第15装甲师第1步兵联队第88防空团的一门88mm Flak18高射炮。该炮安放在用沙袋垒成的防御阵地中，主要用于对付盟军坦克的进攻。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_24.jpg","description":"1939年秋，波兰战役，一门德军的88mm Flak18高射炮正在向地面目标射击。几名军官正观察战况，地面上堆有多个装有三发炮弹的炮弹箱。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_25.jpg","description":"1940年6月，西线法国战场上的德军一门88mm Flak18高射炮。该炮阵地就在一辆被击毁的法国Char B1 bis坦克旁边，一些炮手隐蔽在坦克后并作好战斗准备，图中骑马的应是传令兵。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_26.jpg","description":"1940年6月，北非战场，隶属德军第33炮兵团第1营的一门88mm Flak18高射炮正在哈尔法亚山口向英军坦克射击。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_27.jpg","description":"1941年冬天，东线苏联战场，德军将一门88mm Flak18高射炮的阵地安置在一个废弃的房屋中。为了保证足够的射角，德军将屋子四周的墙壁打掉，只留下支撑屋顶的立木。通过炮管的高度可知，该炮正在与地面目标交火，屋内地上有一堆柳条制的三发弹药箱，除了一弹药手捧着一枚炮弹准备装填外，弹药箱上还放着备用的炮弹。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_28.jpg","description":"1941年8月，东线苏联战场，在拉脱维亚的米塔瓦城（Mitava）大街上的德军一门用树枝作伪装的88mm Flak18高射炮。显然该炮是用来迎击苏军坦克的。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_29.jpg","description":"东线苏联战场，冬季雪地中，德军将88mm Flak18架设在高处，这样使该炮有更大的视野与射击角度，指向斜下方的炮管在对坦克射击时能发挥更大威力。由于88mm高炮尺寸太大，即使在炮坑中也使其难以隐藏和保护，所以在高处设立阵地是十分有优势的。图中的炮组人员正聚精会神地观察前方远处，似要透过薄雾确定逐渐逼近的苏军坦克。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_30.jpg","description":"1941年秋天，东线苏联战场基辅地区，德军一门正在作地面战斗的88mm Flak18高射炮，在乌克兰大草原上，构筑工事作用不大，因此该炮与挂车也只是用树枝作了掩护。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_31.jpg","description":"1942年夏天，东线苏联战场，一门隶属德国空军高炮营的88mm Flak18高射炮班成员已在阵地中作好战斗准备，随时迎击苏军的坦克。注意炮管上的四个“杀伤环”，这是该炮较早前取得的战绩。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_32.jpg","description":"东线苏联战场，冬季雪地中，一门德军的88mm Flak18高射炮在作战斗戒备。88mm高炮的射击距离超出了大多数坦克炮的射程，因此对坦克的杀伤力很大。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_33.jpg","description":"东线苏联战场，德军阵地中一门严阵以待的88mm Flak18高射炮，该炮的炮管上标志表明有不少于36次击毁苏军坦克的战绩。可见该炮组人员的作战经验与射击水平都是很不错的。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_34.jpg","description":"1944年1月，西线意大利战场安齐奥地区，一门德军高炮营的88mm Flak18高射炮班正在阵地中准备迎击登陆的美军。一炮兵指挥官正伏在火炮挂车（Flak18专用的Sd Anh.201特种挂车）上，用望远镜对前方进行观察。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_35.jpg","description":"1945年春，德国本土战场，放置在开阔的积雪地面上的一门德军88mml Flak18高射炮。该炮加装了网状防护罩，并作了基本的冬季伪装。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_36.jpg","description":"1944年9月，在佛罗伦萨的街头战斗中，德国空军一架88毫米高射炮被用作地面作战。该炮班成员身穿德国空军的热带棕褐色制服，很可能是驻扎后方的空军后勤部队一部分，由于战况的变化，他们只能作战场炮兵使用。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_37.jpg","description":"绘画：一辆德军半履带车牵引着一门88mm Flak18高射炮正在半途中休息。由于88mm高射炮的运输重量重达8吨多，因此需用有8吨牵引力的Sdkfz 7半履带车来拖引。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_38.jpg","description":"1941年夏天，东线苏联战场乌克兰地区，一辆德军Sdkfz 7半履带车牵引着一门88mm Flak18高射炮正在涉水渡河。由于河水较浅，这门88mm高炮在201移动台架上亦可安全过河。","caption":""},{"image":"imgs/de/army/de_army_cannonFlak18_39.jpg","description":"在一名军官的监视下，一群德国空军士兵在做88mm Flak18高射炮运输前的准备工作，一名士兵正将Sd Sh.201移动台架与Sdkfz 7半履带车的牵引钩连接，另一些士兵将高炮支撑架抬起并准备用帆布盖住炮管的后膛等处。","caption":""}]}')}});